 const epoch=projectEpoch,serial=gameRun===null?++playSerial:null,generation=playerForStart.generation,view=audioEpoch;
 const current=()=>epoch===projectEpoch&&!document.hidden&&state.events.includes(event)&&playerForStart.generation===generation&&(gameRun===null?serial===playSerial&&view===audioEpoch:true);
