 try{if(!soundFileIds(event).every(id=>audioMixer.root.fileBuffers.has(id))){playerForStart.status='Starting';renderAudio();if(!await ensureAudioFiles(soundFileIds(event),current,event.id)||!current())return false;}else if(cachedPcm()+workletPcm(event.id)+(usesFileProcessor(soundFileIds(event),event)?sourcePcm(soundFileIds(event)):0)>limits.pcm)throw new Error('Stop other Events to free audio memory, or use shorter files.');}catch(error){if(error.name!=='AbortError'&&current()){playerForStart.status='Could not play';releaseIdleAudio();renderAudio();if(gameRun===null)toast(error.message);else reportAudioWarning(error.message);}return false;}
