 if(typeof name!=='string'||!name.length||name.length>80||/[\u0000-\u001f]/.test(name)){reportAudioWarning('lyd.audio.play needs an Event name string (1–80 characters).');return;}
 const event=state.events.find(event=>event.name===name);
 if(!event){reportAudioWarning(`Unknown Event "${name}". Create it in Audio or use its exact name.`);return;}
 const asset=state.assets.find(a=>a.id===event.assetId&&a.type==='audio');
 if(!asset?.data||eventStatus(event)==='Loading'){reportAudioWarning(`Event "${name}" has no ready audio. Load a file in Sound, wait for Ready, then press the key again.`);return;}
