async function init(){tooltips=mountTooltips({document,window});audioView=mountAudioWorkspace($('audio-panel'));renderAudio();state.assets=demoAssets();editor=CodeMirror.fromTextArea($('code'),{mode:'lua',lineNumbers:true,tabSize:2,indentUnit:2,indentWithTabs:false,lineWrapping:false,viewportMargin:20,extraKeys:{'Tab':cm=>cm.replaceSelection('  '),'Ctrl-Enter':()=>run(true),'Cmd-Enter':()=>run(true),'Ctrl-S':save,'Cmd-S':save}});editor.setValue(state.code);editor.on('beforeChange',(_,change)=>{if(switchingScript||!activeScript())return;try{const code=editor.getValue(),from=editor.indexFromPos(change.from),to=editor.indexFromPos(change.to);checkScriptBudget(state,activeScriptId,code.slice(0,from)+change.text.join('\n')+code.slice(to));}catch(error){change.cancel();toast(error.message);}});editor.on('change',()=>{if(switchingScript||!activeScript())return;setScriptCode(state,activeScriptId,editor.getValue());if(!updatingReferenceCode)changed();});luaTools=mountLuaTools({editor,project:()=>({events:state.events,assets:state.assets,sourceName:activeScriptName(),scripts:projectScripts(state)}),onJump:jumpToError,document,window});bindUI();bindPreview();let restored=false;const startupRevision=revision,startupEpoch=projectEpoch;try{let recovered=null;try{recovered=await recovery.load();}catch(error){$('recovery-state').textContent='Recovery unavailable · Save project';recoveryWarning=true;toast('Browser recovery is unavailable. Save project files to keep your work.');}if(!recovered){const raw=localStorage.getItem(STORE);if(raw)recovered={project:validateProject(JSON.parse(raw)),blobs:new Map()};}if(recovered&&startupRevision===revision&&startupEpoch===projectEpoch){const p=validateProject(recovered.project);for(const a of p.assets)if(a.type==='image')await decodeImage(a.data);applyProject(p,recovered.blobs);restored=true;void persistRecovery();toast('Your previous prototype session was restored.');}}catch{toast('The previous session could not be restored. The demo is ready.');}selectedId=null;renderAssets();renderAssetWorkspace();updateSave();drawIdle();requestAnimationFrame(()=>editor.refresh());if(!restored)await run();}
